style.css:
@-moz-document domain("youtube.com") {
body, ytd-app {
        background-color: #e0f7ff !important;
    }

    ytd-masthead, ytd-guide-section-renderer, ytd-mini-guide-renderer {
        background-color: #b3e5fc !important;
    }

    yt-formatted-string, #video-title, .title, .style-scope {
        color: #004b6b !important;
    }

    ytd-thumbnail, ytd-video-renderer, ytd-playlist-renderer {
        background-color: #cceeff !important;
    }

    ytd-video-renderer:hover, ytd-playlist-renderer:hover {
        background-color: #b3e5fc !important;
    }
}
